{
  "name": "@softmill/opencode-mem0-oss",
  "version": "0.2.0",
  "type": "module",
  "description": "Mem0 persistent memory plugin for OpenCode, targeting self-hosted Mem0 OSS servers — add, search, and manage memories across sessions",
  "main": "dist/index.js",
  "types": "index.d.ts",
  "exports": {
    ".": {
      "types": "./index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "publishConfig": {
    "access": "public"
  },
  "license": "Apache-2.0",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "mem0",
    "mem0-oss",
    "self-hosted",
    "memory",
    "ai-memory",
    "persistent-memory"
  ],
  "files": [
    "dist",
    "index.d.ts",
    "LICENSE",
    "opencode-skills"
  ],
  "scripts": {
    "build": "bun build opencode-mem0-oss.ts --outdir dist --target bun --format esm --entry-naming index.[ext]",
    "dev": "bun build opencode-mem0-oss.ts --outdir dist --target bun --format esm --entry-naming index.[ext] --watch",
    "type-check": "tsc --noEmit",
    "test": "bun test",
    "prepack": "bun run build",
    "postpack": ""
  },
  "opencode": {
    "type": "plugin",
    "hooks": [
      "config",
      "chat.message",
      "tool.execute.before",
      "tool.execute.after",
      "experimental.chat.messages.transform",
      "experimental.session.compacting",
      "shell.env"
    ]
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.0.162"
  },
  "devDependencies": {
    "bun-types": ">=1.3.14",
    "typescript": "^5.7.3"
  }
}
